import raw from "@/lib/data/metagenics/catalog.json"
import type { ContentBlock, ProductQA, Rating, SupplementFacts, Variant } from "@/types"

/** Shape of catalog.json, generated by scripts/import-metagenics.mjs. */
export interface CatalogProduct {
  slug: string
  name: string
  subtitle?: string
  summary?: string
  sourceUrl: string
  image?: string
  categories: string[]
  isBundle: boolean
  productLine?: string
  form: string
  rating?: Rating
  variants: Variant[]
  description: ContentBlock[]
  supplementFacts?: SupplementFacts | null
  directions?: string
  storage?: string
  cautions?: string
  warnings?: string
  faq: ProductQA[]
  related: string[]
}

export interface CatalogFile {
  source: { repo: string; batch: string; products: number }
  categories: { slug: string; name: string; sourceUrl: string; count: number }[]
  products: CatalogProduct[]
}

export const catalog = raw as unknown as CatalogFile
